import{_ as o}from"./chunks/home.pc.ko.DgmCh8Ar.js";import{_ as r}from"./chunks/home-estop.pc.ko.DDxZsvoM.js";import{_ as n,o as e,c as s,a5 as a}from"./chunks/framework.D47SInms.js";const k=JSON.parse('{"title":"제어 홈","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/control-home.md","filePath":"ko/manual/gui/control-home.md","lastUpdated":1791600043000}'),d={name:"ko/manual/gui/control-home.md"};function l(g,t,i,c,h,m){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="제어-홈" tabindex="-1">제어 홈 <a class="header-anchor" href="#제어-홈" aria-label="Permalink to &quot;제어 홈&quot;">​</a></h1><p>제어 홈은 로봇을 조종하는 화면입니다. 허브에서 <strong>컨트롤</strong>을 눌러 엽니다. 화면 전체가 뷰포트여서 카메라 영상이나 3D 뷰가 여기에 나오고, 왼쪽에는 모션 카드, 오른쪽에는 <strong>관측</strong> 카드가 붙습니다. 게임패드가 없으면 아래 양쪽 구석에 가상 조이스틱이 하나씩 생깁니다.</p><p><img src="'+o+'" alt="제어 홈"></p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>이 화면의 모션 버튼은 모두 실제 로봇을 움직입니다. <strong>로봇이 움직이는 동안에는 사람·동물·장애물을 로봇에서 2 m 이상 떨어뜨려 두십시오.</strong> 버튼을 누르기 전에 주변을 살피고, <code>E-STOP</code>에 손이 닿는 자리에 있으십시오.</p></div><h2 id="상단바" tabindex="-1">상단바 <a class="header-anchor" href="#상단바" aria-label="Permalink to &quot;상단바&quot;">​</a></h2><p>상단바는 영상 위에 두 묶음으로 나뉘어 떠 있습니다. 왼쪽부터 순서대로 봅니다.</p><table tabindex="0"><thead><tr><th>요소</th><th>표시 / 동작</th></tr></thead><tbody><tr><td>로고</td><td><strong>허브</strong>로 갑니다. 로봇은 그 자리에 서고, 연결은 끊기지 않습니다</td></tr><tr><td>상태 불빛</td><td>초록·주황·빨강 중 하나가 천천히 깜빡입니다. 위험하면 빠르게 깜빡이고, 연결되지 않았으면 깜빡이지 않는 빨강입니다. 탭하면 <strong>시스템 종합 상태</strong>가 열립니다(<a href="/RBQ/nightly/ko/manual/gui/connection.html#connection-status-in-the-top-bar">연결</a> 참고)</td></tr><tr><td>보행 칩</td><td>로봇의 현재 보행 상태 이름을 상태별 색으로 보여 줍니다(예: <code>STANDING</code>). 연결되지 않았으면 보이지 않습니다</td></tr><tr><td><code>SLAM</code> 칩</td><td>외부 조종(SLAM·SDK)이 켜져 있을 때만 나타납니다. 탭하면 조종권이 앱으로 돌아옵니다</td></tr><tr><td>신호 막대</td><td>WiFi 신호 세기와, 로봇 링크로 지금 오가는 속도</td></tr><tr><td>로그 배지</td><td>아직 확인하지 않은 로그 알림</td></tr><tr><td><strong>로봇</strong> 배터리, 기기 배터리</td><td>로봇 배터리 잔량(충전 중이면 충전 표시)과 이 기기의 배터리</td></tr><tr><td><code>E-STOP</code></td><td>비상 정지 — 아래에서 설명합니다</td></tr><tr><td>종료</td><td>데스크탑 빌드에만 있습니다. <strong>앱을 종료할까요?</strong> 로 한 번 물어본 뒤 앱을 닫습니다. 로봇은 계속 동작합니다</td></tr></tbody></table><p>로봇이 끊긴 뒤 8초가 지나도 다시 붙지 않으면 앱이 스스로 허브로 넘어갑니다. 연결은 허브에서 하기 때문입니다. 연결된 로봇이 바뀌는 순간에도 허브로 돌아가니, 고르지 않은 로봇을 조종하게 될 일은 없습니다.</p><h3 id="e-stop" tabindex="-1">E-STOP <a class="header-anchor" href="#e-stop" aria-label="Permalink to &quot;E-STOP&quot;">​</a></h3><p><code>E-STOP</code>은 한 번 탭으로는 발동하지 않습니다. 누르면 <strong>비상 정지하시겠습니까?</strong> 확인 창이 열리고, <em>로봇이 즉시 모든 동작을 멈추고 힘을 차단합니다. 제어를 다시 시작하려면 재초기화가 필요합니다.</em> 라고 알려 줍니다. <strong>정지</strong>를 누르면 실행하고, <strong>취소</strong>를 누르면 돌아갑니다. 메뉴가 열려 있을 때를 포함해 어느 화면에서나 똑같이 동작합니다.</p><p><img src="'+r+'" alt="E-STOP 확인"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>비상 정지한 뒤에는 로봇에 모터 전원이 들어오지 않습니다. 다시 움직이려면 아래 <strong>자동 기동</strong>으로 되살려야 합니다. 시퀀스가 어디서 멈췄는지는 단계 칩이 알려 줍니다.</p></div><h3 id="소유권" tabindex="-1">소유권 <a class="header-anchor" href="#소유권" aria-label="Permalink to &quot;소유권&quot;">​</a></h3><p>로봇은 한 번에 한 기기만 조종합니다. 다른 기기가 제어권을 쥐고 있으면 상태 불빛이 주황으로 바뀌고, <strong>시스템 종합 상태</strong>의 <strong>소유권</strong> 행에 <code>가져오기 ▸</code> 가 뜹니다 — 탭하면 제어권을 되찾습니다. SLAM이나 SDK 프로그램이 조종하는 동안에는 대신 <code>SLAM</code> 칩이 보입니다.</p><p>다른 기기가 제어권을 쥐고 있는 동안 이 기기는 관전합니다. 화면은 그대로 보이고 상단 바 아래 조작은 잠기며, 위쪽 <code>관전</code>을 누르면 제어권을 가져올 수 있습니다. <a href="/RBQ/nightly/ko/manual/gui/emergency.html#spectating">관전</a> 참고.</p><h2 id="자동-기동" tabindex="-1">자동 기동 <a class="header-anchor" href="#자동-기동" aria-label="Permalink to &quot;자동 기동&quot;">​</a></h2><p>로봇의 모터 제어가 켜지기 전까지는 뷰포트 아래 중앙에 초록색 <strong>자동 기동</strong> 버튼이 떠 있습니다. 연결되지 않았으면 회색입니다. 탭하면 <strong>자동 기동</strong> 창이 열립니다. 창은 항상 화면 가운데에 고정됩니다 — 화면이 짧으면 창 안의 <strong>기동 시퀀스</strong> 목록만 스크롤되고 버튼은 늘 보입니다. 가로로 든 폰처럼 화면이 낮으면 단계마다 한 줄로 접혀 나오고, 줄을 탭하면 세부가 펼쳐지거나 접힙니다. 진행 중인 단계와 실패·경고가 난 단계는 저절로 펼쳐집니다.</p><ol><li>안내를 먼저 읽습니다 — <em>로봇을 평평한 바닥에 두고 모든 발과 무릎이 지면에 닿아 있는지 확인하세요.</em></li><li>단계 칩 다섯 개가 시퀀스를 보여 줍니다: <strong>POWER</strong>, <strong>CAN-BUS</strong>, <strong>HOMING</strong>, <strong>IMU-CHECK</strong>, <strong>START</strong>. 아직 끝나지 않은 <strong>CAN-BUS</strong>·<strong>HOMING</strong> 칩은 탭해서 그 단계만 따로 돌릴 수 있습니다.</li><li><strong>자동 기동</strong>을 누릅니다. 창은 그대로 열려 있고, 칩 아래 <strong>기동 시퀀스</strong> 패널이 사전 확인 → Leg 전원 → 관절 통신 → 모터 파라미터 → 홈 위치 → IMU → 제어 활성 순으로 <strong>통과 / 실패 / 경고 / 진행 중</strong>을 하나씩 채웁니다.</li><li>어느 단계가 실패하면 패널이 원인과 조치를 함께 알려 줍니다. 예를 들어 <em>이미 서 있는 상태입니다 — 로봇을 앉힌 뒤 다시 시작하세요.</em> 처럼 나옵니다. 조치한 뒤 <strong>다시 시작</strong>을 누릅니다.</li><li>시퀀스가 <strong>완료</strong>로 바뀌면 <strong>닫기</strong>를 누릅니다. 이 창에서 지켜본 기동이 마지막 단계까지 통과하면 <strong>다시 시작</strong>이 사라지고 <strong>닫기</strong>만 남습니다. 실수로 두 번 돌릴 일이 없습니다.</li></ol><p>같은 시퀀스를 상태 불빛에서도 시작할 수 있습니다: <strong>시스템 종합 상태 › ▶ 자동 기동 (전체 시퀀스)</strong>.</p><h2 id="뷰포트와-소스-선택" tabindex="-1">뷰포트와 소스 선택 <a class="header-anchor" href="#뷰포트와-소스-선택" aria-label="Permalink to &quot;뷰포트와 소스 선택&quot;">​</a></h2><p>뷰포트 위쪽 중앙의 드롭다운으로 무엇을 볼지 고릅니다. 로봇의 실시간 모델인 <code>3D</code>는 언제나 있고, 카메라 소스는 로봇이 그 카메라를 알아봤을 때만 목록에 올라옵니다: <strong>전방</strong>, <strong>후방</strong>, <strong>좌측</strong>, <strong>우측</strong>, <strong>계단</strong>, <strong>4분할</strong>, <strong>파노라마</strong>, <code>CCTV</code>, <strong>열화상</strong>, <strong>PTZ 합성</strong>, 그리고 LiDAR 장착 로봇의 <code>SLAM</code>. 목록 바깥을 탭하면 소스를 바꾸지 않고 닫힙니다.</p><p>PTZ 계열 소스를 고르면 팬·틸트·줌 패널이 영상 위에 뜹니다. 손잡이를 잡아 옮길 수 있습니다.</p><p>도킹이 도는 동안에는 선택기가 <code>도킹</code>으로 바뀌고 열리지 않습니다 — 닫을 때까지 뷰포트는 <a href="/RBQ/nightly/ko/manual/gui/camera-vision.html#dock-view">Dock View</a>가 씁니다.</p><h2 id="왼쪽-카드-—-모션" tabindex="-1">왼쪽 카드 — 모션 <a class="header-anchor" href="#왼쪽-카드-—-모션" aria-label="Permalink to &quot;왼쪽 카드 — 모션&quot;">​</a></h2><p>로봇을 움직이는 것은 모두 왼쪽에 모여 있습니다.</p><ul><li><strong>카드</strong>: 접혀 있으면 걷는 사람 아이콘이 든 둥근 유리 버튼입니다. 누르면 동그라미가 카드로 늘어나고, 카드 윗줄을 누르면 다시 접힙니다. 카드마다 펼침 상태를 기억하며, 처음에는 둘 다 펼쳐져 있습니다.</li><li><strong>본문</strong>: 고정 모션 버튼 <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, <code>STAIRS</code>, <code>DOCKING</code>(도킹이 가능할 때만), 그리고 전체 모션 그리드를 여는 점선 버튼 <strong>모션</strong>이 있습니다. 로봇의 현재 보행 상태와 맞는 버튼이 강조됩니다. <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a>을 참고하세요.</li><li><strong>도구 버튼</strong>: 카드 밖, 왼쪽 조이스틱 바로 오른쪽에 작은 버튼이 한 줄로 놓입니다. 게임패드 모드에서는 왼쪽 가장자리로 갑니다. 하나를 누르면 그 줄 위로 해당 패널이 열립니다. <ul><li><strong>주행</strong> — 속도·본체 높이·기울기 슬라이더 (<a href="/RBQ/nightly/ko/manual/gui/motion-commands.html#drive-parameters">주행 파라미터</a>).</li><li><strong>팔</strong> — 매니퓰레이터가 달린 로봇에만 나옵니다.</li><li><strong>조종</strong> — 입력 모드 <strong>자동 / 가상 / 패드</strong>와 실시간 게임패드 입력 맵. <em>자동</em>은 물리 게임패드가 연결되면 그쪽으로 넘깁니다. 초록 점이 있으면 외부 조종이 주행을 맡고 있다는 뜻입니다.</li></ul></li><li>카드가 화면보다 길면 아래에 <code>▾</code>가 붙어 스크롤된다는 것을 알려 줍니다.</li></ul><h2 id="오른쪽-카드-—-관측" tabindex="-1">오른쪽 카드 — 관측 <a class="header-anchor" href="#오른쪽-카드-—-관측" aria-label="Permalink to &quot;오른쪽 카드 — 관측&quot;">​</a></h2><p><em>무엇을 보고 듣는가</em>에 해당하는 것은 모두 오른쪽에 있습니다.</p><ul><li><strong>카드</strong>: 접혀 있으면 둥근 유리 버튼이고, 펼치고 접는 방식은 왼쪽 카드와 같습니다.</li><li><strong>본문</strong>: <ul><li><strong>비전</strong> — 비전 토글이 모여 있습니다. <strong>P2G</strong>(Point-to-Go)도 여기 있는데, 소스가 <strong>전방</strong>일 때만 쓸 수 있습니다. P2G를 켜 두면 영상 속 바닥의 한 지점을 탭할 때 로봇이 그곳으로 걸어갑니다.</li><li><strong>3D 씬</strong> — 3D 뷰 설정. 소스가 <code>3D</code>일 때만 나옵니다.</li><li><strong>오디오</strong> — 로봇 소리 듣기, 볼륨, 장치. 초록 점이 있으면 듣기가 켜져 있습니다.</li><li><code>SLAM</code> — LiDAR 장착 로봇에만 나옵니다.</li><li><strong>PTZ</strong> — PTZ 카메라가 달린 로봇에만 나옵니다. 화면을 PTZ 카메라로 바꾸고, 다시 누르면 직전 소스로 돌아갑니다.</li></ul></li><li><strong>워키토키</strong>: 오른쪽 아래 버튼입니다. 오른쪽 조이스틱 바로 왼쪽에 있고, 게임패드 모드에서는 오른쪽 가장자리로 갑니다. 누르고 있는 동안 로봇 스피커로 말이 나가며, 그동안 <strong>송출 중</strong>으로 표시됩니다. 스피커 앰프가 꺼져 있으면 흐리게 보이고 눌리지 않습니다.</li><li><strong>사운드 · 촬영</strong>: <code>워키토키</code> 바로 왼쪽의 버튼 둘입니다. <code>사운드</code>는 소리를 골라 로봇에서 반복 재생합니다. <code>촬영</code>을 누르면 <code>사진</code>과 <code>녹화</code> 중 하나를 고르고, 녹화 중에는 버튼에 빨간 경과 시간이 뜨며 다시 누르면 멈춥니다. 화면이 좁아 가운데 계기와 닿으면 두 버튼이 <code>워키토키</code> 위로 세로로 쌓입니다. 자세한 내용은 <a href="/RBQ/nightly/ko/manual/gui/media.html#control-home">미디어</a>를 보세요.</li><li><strong>자이로</strong>와 <strong>속도 HUD</strong>는 영상 아래 중앙에 나란히 있습니다. 자이로를 탭하면 커집니다. 둘 다 <strong>앱 설정</strong>에서 끌 수 있습니다.</li><li><strong>시뮬레이터</strong>에서는 좌우 카드가 없고 화면을 3D 로 꽉 채웁니다. 로봇은 늘 걷기 상태이고, 아래 도구 줄에 <code>주행</code>·<code>레벨</code>·<code>리셋</code>이 놓입니다. 시점은 위 가운데 드롭다운에서 고릅니다. 진행 상황은 그 아래에 표시됩니다. 레벨과 시점은 <a href="./connection.html">연결</a>의 시뮬레이터 설명을 보세요.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>P2G</strong>가 켜진 동안에는 영상 전체가 명령 영역입니다 — 바닥을 탭할 때마다 로봇이 움직입니다. 다 쓰면 반드시 끄십시오.</p></div><h2 id="조이스틱과-입력-모드" tabindex="-1">조이스틱과 입력 모드 <a class="header-anchor" href="#조이스틱과-입력-모드" aria-label="Permalink to &quot;조이스틱과 입력 모드&quot;">​</a></h2><ul><li><strong>게임패드가 없으면</strong> — 터치 기기와 PC에서는 가상 조이스틱 두 개가 나옵니다. 축이 무엇을 하는지는 현재 모션에 따라 달라집니다. <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a>의 축 표를 보세요.</li><li><strong>게임패드가 있으면</strong> — 물리 패드든 Steam Deck이든 가상 조이스틱이 사라지고 패드의 스틱으로 조종합니다. 영상을 넓게 보려면 카드를 접으십시오.</li><li>설정 › 게임패드의 <strong>원 스틱 모드</strong>는 좌우 스틱 역할을 바꿔 한 손으로도 조종할 수 있게 합니다.</li></ul><p><strong>키보드로 조종하기</strong> — 게임패드가 없는 PC에서는 가상 조이스틱과 함께 키보드로도 조종할 수 있습니다. 이 화면에서만 듣습니다. 허브나 설정에서는 같은 키를 눌러도 로봇이 꿈쩍하지 않습니다.</p><table tabindex="0"><thead><tr><th>키</th><th>하는 일</th></tr></thead><tbody><tr><td><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd></td><td>왼쪽 스틱 — 앞뒤 · 좌우</td></tr><tr><td><kbd>Q</kbd> <kbd>E</kbd></td><td>오른쪽 스틱 좌 / 우 — 좌 / 우 회전</td></tr><tr><td><kbd>↑</kbd> <kbd>↓</kbd> <kbd>←</kbd> <kbd>→</kbd></td><td>오른쪽 스틱</td></tr></tbody></table><p>키를 누르고 있는 동안 로봇이 움직이고, 떼면 멈춥니다. 키보드에는 비상 정지 키가 없습니다 — <strong>E-STOP은 화면 오른쪽 위 버튼</strong>입니다.</p><p>연결된 동안에는 왼쪽 아래 구석에 현재 보행 상태 이름이 작은 HUD로 뜹니다.</p><h2 id="컴팩트-레이아웃" tabindex="-1">컴팩트 레이아웃 <a class="header-anchor" href="#컴팩트-레이아웃" aria-label="Permalink to &quot;컴팩트 레이아웃&quot;">​</a></h2><p>세로가 짧은 화면, 그러니까 폰이나 높이 500 px 미만의 창에서는 배치를 그대로 두고 요소만 작아집니다. 조이스틱·도구 버튼·워키토키는 구석으로 작게 들어가고, 왼쪽 카드는 그 위 공간까지만 차지하며 스크롤됩니다. 가로가 좁은 화면에서는 카드 폭도 좁아집니다. 빠지는 기능은 없습니다.</p><p>폭이 720 px 미만인 아주 작은 화면(작은 폰 가로 등)에서는 표시를 덜어 냅니다. 아래 도구 버튼과 <code>워키토키</code> 옆 버튼은 글자 없이 아이콘만 남고, 오른쪽 위 <code>E-STOP</code>은 비상 아이콘만 보이며, 전송량 칸의 신호 막대와 가운데 자이로가 작아지거나 빠집니다. 기능은 그대로입니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#control-home">개발자 모드</a>에 모아 두었습니다.</p></blockquote>',40)])])}const P=n(d,[["render",l]]);export{k as __pageData,P as default};
